//region CITY RESOURCE CONTAINER
interface CityResourceContainerInternalProps extends CommerceCityResourceData {
	parentIsFocusedOrSelected: Accessor<boolean>;
}
const CityResourceContainerInternalSymbol = Symbol();
const CityResourceContainerInternal: Component<CityResourceContainerInternalProps> = (props) => {
	const model = useCommerceScreenContext();
	const imageCache = useImageCache();

	const [mouseIsOverCity, setMouseIsOverCity] = createSignal(false);

	const images = {
		ticketHighlightedCSS: "url(blp:base_ticket-select-bg)",
		ticketPositiveCSS: "url(blp:base_ticket-positive_bg)",
		ticketNegativeCSS: "url(blp:base_ticket-negative_bg)",
		resourceEmptySlotCSS: "url(blp:resource_empty_slotv2)",
		successIconCSS: "url(blp:dip_esp_success_icon)",
		failIconCSS: "url(blp:dip_esp_fail_icon)",
	};

	imageCache.registerImages(CityResourceContainerInternalSymbol, Object.values(images));

	// Can't cache these icons as input/gamepad type can change any time
	const [bottomButtonIconCSS, setBottomButtonIconCSS] = createSignal("");
	const [leftButtonIconCSS, setLeftButtonIconCSS] = createSignal("");

	createEffect(() => {
		setBottomButtonIconCSS(`url(blp:${IconUtils.getIconFromActionName("accept", ActiveInputDevice()) ?? ""})`);
		setLeftButtonIconCSS(
			`url(blp:${IconUtils.getIconFromActionName("shell-action-1", ActiveInputDevice()) ?? ""})`,
		);
	});

	const selectionState = createMemo(() =>
		model.getResourceContainerSelectionState(model.cityIsConnectedToTradeNetwork(props.cityID), {
			cityID: props.cityID,
			canAssignResourceToSettlement: props.canAssignSelectedResourceToSettlement,
		}),
	);

	const getEmptySlotOpacity = () => {
		if (model.selectedResource().resourceValue === -1) {
			return "opacity-50";
		}
		if (
			model.selectedResource().cityID?.id === props.cityID.id ||
			selectionState() === ResourceContainerSelectionState.CanNotSelect
		) {
			return "opacity-10";
		}
		if (selectionState() === ResourceContainerSelectionState.CanSelect) {
			return "opacity-80";
		}
		return "opacity-50";
	};

	const canDrop: DragDropPredicateT<ResourceSlotData, DropzoneData> = (draggable, dropzone) => {
		const memo = createMemo(() => {
			if (model.isInSortAndFilterMode()) {
				return false;
			}
			if (dropzone.data.resourceValue) {
				return model.canDropResourceOnTarget(draggable.data, props.cityID, dropzone.data.resourceValue);
			}
			return selectionState() === ResourceContainerSelectionState.CanSelect;
		});
		return memo;
	};

	const isReturnResourcesEnabled = createMemo(
		() =>
			model.isSlottingAvailable &&
			props.slottedResources.length > 0 &&
			model.selectedResource().resourceValue === -1,
	);

	const settlementIsFocused = createMemo(() =>
		ComponentID.isMatch(model.focusedSettlementId() ?? null, props.cityID),
	);
	const settlementIsSelected = createMemo(() =>
		ComponentID.isMatch(model.selectedSettlementId() ?? null, props.cityID),
	);

	const shouldShowGhostResource = createMemo(() => {
		const hasSelectedResource = model.selectedResource().resourceValue !== -1;
		const settlementIsSelectedOrFocused = settlementIsFocused() || settlementIsSelected();
		const settlementIsNotUnselectable = selectionState() !== ResourceContainerSelectionState.CanNotSelect;
		const selectedResourcesIsInSettlement = ComponentID.isMatch(
			model.selectedResource().cityID ?? null,
			props.cityID,
		);
		return (
			IsControllerActive() &&
			hasSelectedResource &&
			settlementIsSelectedOrFocused &&
			settlementIsNotUnselectable &&
			!selectedResourcesIsInSettlement
		);
	});

	const autoFocusGhost = createMemo(() => {
		if (model.isInSortAndFilterMode()) {
			return false;
		}
		// The ghost resource only exists in quite a specific condition, meaning we can
		// simplify the autoFocus rule to just when you select this settlement while having a resource selected
		return settlementIsSelected() && model.selectedResource().resourceValue !== -1;
	});

	return (
		<div class="flex items-center flex-col relative">
			<CardFrame
				tabIndex={-1}
				onFocus={() => setMouseIsOverCity(true)}
				onBlur={() => setMouseIsOverCity(false)}
				class={`w-full mt-3 mb-2 px-4 pb-4 ${selectionState() === ResourceContainerSelectionState.CanSelect || selectionState() === ResourceContainerSelectionState.CanNotSelect ? "pt-5" : "pt-4"} flex flex-col relative`}
				style={
					IsControllerActive() && props.parentIsFocusedOrSelected()
						? { "border-image-source": images.ticketHighlightedCSS }
						: selectionState() === ResourceContainerSelectionState.CanSelect
							? mouseIsOverCity()
								? { "border-image-source": images.ticketHighlightedCSS }
								: {
										"border-image-source": images.ticketPositiveCSS,
									}
							: selectionState() === ResourceContainerSelectionState.CanNotSelect
								? {
										"border-image-source": images.ticketNegativeCSS,
									}
								: {}
				}
			>
				<Dropzone
					debugId={"City-" + getCityName(props.cityID)}
					data={{ cityID: props.cityID }}
					canDrop={canDrop}
					onDragOver={() => setMouseIsOverCity(true)}
					onDragLeave={() => setMouseIsOverCity(false)}
					onDragDrop={() => setMouseIsOverCity(false)}
					debugTrace={DEBUG_DRAG_AND_DROP}
				>
					<div class="flex flex-row flex-wrap relative w-full justify-between">
						<Show
							when={model.selectedResource().resourceValue === -1}
							fallback={<SettlementName {...props.settlementNameData} />}
						>
							<Activatable
								disableFocus={true}
								onActivate={() => {
									model.clickCityName(props.cityID);
								}}
							>
								<SettlementName {...props.settlementNameData} />
							</Activatable>
						</Show>
						<Show when={props.factoryResourceData.hasFactory}>
							<FactoryTypeDisplay {...props.factoryResourceData} />
						</Show>
					</div>
					<Divider.Horizontal margin={2} />
					<div class="flex flex-row items-center">
						<div class="flex flex-row max-h-full items-end">
							{
								<For each={props.yieldDeltas}>
									{(yieldDelta, index) => (
										<YieldDelta
											classList={{
												"ml-3": index() > 0 && index() < props.yieldDeltas.length,
											}}
											yieldIconSrc={yieldDelta.yieldIconSrc}
											yieldTotal={yieldDelta.yieldTotal}
											yieldDelta={yieldDelta.yieldDelta}
										/>
									)}
								</For>
							}
						</div>
						<Divider.Vertical margin={2} />
						<div class="flex-auto flex flex-row">
							<div
								class="flex-auto"
								data-name={`city-resource-container-${Locale.compose(props.settlementNameData.settlementName)}`}
							>
								<div class="flex flex-row flex-wrap mt-4 flex-auto">
									<Show
										when={props.slottedResources.length > 0}
										fallback={
											//Stops a blank "" being rendered by a For loop with no iterations
											<div class="hidden" />
										}
									>
										<For each={props.slottedResources}>
											{(slottedResource, slotIndex) => {
												const [resourceIsActiveDropzone, setResourceIsActiveDropzone] =
													createSignal(false);
												const resourceName = createMemo(() =>
													getResourceName({
														cityID: slottedResource.cityID,
														resourceValue: slottedResource.resourceValue,
													}),
												);
												return (
													<Dropzone
														// Needs an explicit size to avoid a coherent bug where classless divs
														// end up too big if sibling elements have wrapped to a new line
														class="size-19 mb-1"
														debugId={"Resource Dropzone-" + resourceName()}
														data={{
															cityID: props.cityID,
															resourceValue: slottedResource.resourceValue,
														}}
														canDrop={canDrop}
														debugTrace={DEBUG_DRAG_AND_DROP}
														onDragOver={() => setResourceIsActiveDropzone(true)}
														onDragLeave={() => setResourceIsActiveDropzone(false)}
														onDragDrop={() => setResourceIsActiveDropzone(false)}
													>
														<DraggableResource
															resourceData={slottedResource}
															isFirstResourceInSection={slotIndex() === 0}
															isActiveDropzone={resourceIsActiveDropzone()}
														/>
													</Dropzone>
												);
											}}
										</For>
									</Show>
									<For each={props.availableSlots}>
										{(_availableSlot, index) => (
											<Show
												when={index() === 0 && shouldShowGhostResource()}
												fallback={
													<div
														class={`size-16 mb-2 mr-3 bg-contain bg-no-repeat bg-center relative flex items-center justify-center ${getEmptySlotOpacity()}`}
														style={{
															"background-image": images.resourceEmptySlotCSS,
														}}
													/>
												}
											>
												<div class="size-16 mr-3 relative flex flex-row justify-center">
													<Activatable
														name="assignment-slot"
														autoFocus={autoFocusGhost()}
														class="hover\:scale-125 focus\:scale-125 relative"
														classList={{
															"opacity-20": !model.ghostResourceFocused(),
															"opacity-60 focused-resource": model.ghostResourceFocused(),
														}}
														disableFocus={settlementIsSelected() === false}
														disabled={settlementIsSelected() === false}
														onFocus={() => {
															model.setGhostResourceFocused(true);
															model.setFocusedResource({ resourceValue: -1 });
														}}
														onBlur={() => model.setGhostResourceFocused(false)}
														onActivate={() => {
															model.slotSelectedResource(props.cityID);
															model.setSelectedSettlementId(undefined);
														}}
													>
														<FramedResource {...model.getSelectedResourceProps()!} />
													</Activatable>
													<Show
														when={
															!model.selectedSettlementId() ||
															model.ghostResourceFocused()
														}
													>
														<Icon
															class="absolute size-8 top-0"
															name={
																settlementIsSelected()
																	? bottomButtonIconCSS()
																	: leftButtonIconCSS()
															}
															isUrl
														/>
													</Show>
												</div>
											</Show>
										)}
									</For>
								</div>
							</div>
							<Show when={IsControllerActive() === false}>
								<Tooltip.Text
									text={Locale.compose(
										"LOC_COMMERCE_UNASSIGN_RESOURCES",
										Locale.compose(props.settlementNameData.settlementName),
									)}
								>
									<AudioContextProvider segment="ReturnResources">
										<Show
											when={isReturnResourcesEnabled()}
											fallback={
												<ReturnResourceButton
													class="mr-1"
													disabled
												/>
											}
										>
											<ReturnResourceButton
												class="mr-1"
												onActivate={() => {
													model.clearAllResources(props.cityID);
												}}
											/>
										</Show>
									</AudioContextProvider>
								</Tooltip.Text>
							</Show>
						</div>
					</div>
				</Dropzone>
			</CardFrame>
			<Show
				when={selectionState() === ResourceContainerSelectionState.CanSelect}
				fallback={
					<Show when={selectionState() === ResourceContainerSelectionState.CanNotSelect}>
						<Icon
							class="size-8 absolute top-3"
							name={images.failIconCSS}
							isUrl={true}
						/>
					</Show>
				}
			>
				<Icon
					class="size-8 absolute top-3"
					name={images.successIconCSS}
					isUrl={true}
				/>
			</Show>
		</div>
	);
};

interface CityResourceContainerProps extends CommerceCityResourceData {
	cityIndex: number;
}
const CityResourceContainer: Component<CityResourceContainerProps> = (props) => {
	const model = useCommerceScreenContext();

	const [isFocused, setIsFocused] = createSignal(false);

	const dndContext = useDragAndDropContext();

	const isFocusable = createMemo(() => {
		if (model.isInSortAndFilterMode()) {
			return false;
		}

		if (IsControllerActive()) {
			return model.selectedSettlementId() === undefined;
		}

		const isResourceSelected = model.selectedResource().resourceValue !== -1;
		const isDragging = dndContext.isDragging();
		if (isDragging === null && isResourceSelected) {
			return true;
		}

		return false;
	});

	const selectionState = createMemo(() =>
		model.getResourceContainerSelectionState(model.cityIsConnectedToTradeNetwork(props.cityID), {
			cityID: props.cityID,
			canAssignResourceToSettlement: props.canAssignSelectedResourceToSettlement,
		}),
	);

	const isDisabled = createMemo(() => {
		return selectionState() === ResourceContainerSelectionState.CanNotSelect;
	});

	const onFocus = () => {
		debugGamepadLog("onFocus called for", getCityName(props.cityID));
		model.setFocusedSettlementId(props.cityID);
		// If we're focused on a settlement, we can't be focused on a resource
		// This is here instead of in DraggableResource's onBlur so we don't get
		// a double call when navigating between resources in a single section
		// (i.e. one call for unsetting it as we blur and a second for setting
		// it to the new focus)
		model.setFocusedResource({ resourceValue: -1, cityID: undefined });
		setIsFocused(true);
	};

	const onBlur = () => {
		debugGamepadLog("onBlur called for", getCityName(props.cityID));
		setIsFocused(false);
	};

	const cityName = untrack(() => {
		const myCity = Cities.get(props.cityID);
		if (!myCity) {
			return "unknown-city";
		}
		return Locale.compose(myCity.name);
	});
	const playerHasUnassignedResources = createMemo(() =>
		model.data.resourceTabData.availableResourceSectionData.some((section) => {
			return section.subSections.some((subSection) => subSection.resourceSlotData.length > 0);
		}),
	);

	const [autoFocusSettlement, setAutoFocusSettlement] = createSignal(false);

	// Only one auto-focus change is allowed in a given frame, so we need to a specific
	// set of rules for settlements to be the ones pulling exclusive focus
	createEffect(() => {
		if (!IsControllerActive()) {
			setAutoFocusSettlement(false);
			return;
		}

		if (model.isInSortAndFilterMode()) {
			setAutoFocusSettlement(false);
			return;
		}

		// If you deselect a settlement and don't have a resource selected
		const focusSettlementOnSettlementDeselectedWithNoResourceSelected =
			model.selectedResource().resourceValue === -1 &&
			model.prevSelectedSettlementId() &&
			ComponentID.isMatch(props.cityID, model.prevSelectedSettlementId()!);

		// If you select a resource, focus the first settlement that's valid to place it
		const focusSettlementOnResourceSelected =
			model.isFirstAssignableCity(props.cityID) && model.selectedResource().resourceValue !== -1;

		// if you deselect a resource, but don't have any unassigned resources, focus the settlement
		// the deselected resources is assigned to
		const focusSettlementOnResourceDeselectedAndNoUnassignedResources =
			model.prevSelectedResource().resourceValue !== -1 &&
			ComponentID.isMatch(model.prevSelectedResource().cityID ?? null, props.cityID) &&
			!playerHasUnassignedResources();

		const focusInitialSettlementWhenNoAvailableResources = !model.hasUnassignedResources() && props.cityIndex === 0;

		const shouldAutoFocus =
			(!model.selectedSettlementId() &&
				(focusSettlementOnSettlementDeselectedWithNoResourceSelected ||
					focusSettlementOnResourceSelected ||
					focusSettlementOnResourceDeselectedAndNoUnassignedResources)) ||
			focusInitialSettlementWhenNoAvailableResources;

		if (shouldAutoFocus) {
			debugGamepadLog(
				"AUTO-FOCUS " + getCityName(props.cityID),
				"( focusSettlementOnSettlementDeselectedWithNoResourceSelected:",
				focusSettlementOnSettlementDeselectedWithNoResourceSelected,
				",focusSettlementOnResourceSelected:",
				focusSettlementOnResourceSelected,
				",focusSettlementOnResourceDeselectedAndNoUnassignedResources:",
				focusSettlementOnResourceDeselectedAndNoUnassignedResources,
				")",
			);
		}
		setAutoFocusSettlement(shouldAutoFocus);
	});

	return (
		<Activatable
			class="relative"
			tabIndex={props.cityIndex + 1}
			autoFocus={autoFocusSettlement()}
			name={`${cityName}-city-resource-activatable`}
			onActivate={() => {
				if (IsControllerActive()) {
					if (model.settlementHasSlottedResources(props.cityID)) {
						model.setSelectedSettlementId(props.cityID);
					}
				} else {
					model.slotSelectedResource(props.cityID);
				}
			}}
			onFocus={() => onFocus()}
			onBlur={() => onBlur()}
			disabled={isDisabled()}
			disableFocus={!isFocusable()}
			suppressPointerChanges={selectionState() === ResourceContainerSelectionState.NotSelecting}
		>
			<CityResourceContainerInternal
				{...props}
				parentIsFocusedOrSelected={() =>
					isFocused() || ComponentID.isMatch(props.cityID, model.selectedSettlementId() ?? null)
				}
			/>
		</Activatable>
	);
};
