//#region RESOURCES CONTAINER COMPONENT
const CommerceResourcesContainerComponent: Component<ResourceTabData> = (props) => {
	const model = useCommerceScreenContext();

	const audioTrigger = useAudio("DraggableResource");

	const yieldHighlightDropdownItems = [
		"DEFAULT",
		"YIELD_FOOD",
		"YIELD_PRODUCTION",
		"YIELD_GOLD",
		"YIELD_SCIENCE",
		"YIELD_CULTURE",
		"YIELD_HAPPINESS",
		"YIELD_DIPLOMACY",
	];

	const onDragStart: DragStartCallbackT<ResourceSlotData> = (draggable) => {
		const data = draggable.data;

		if (data.cityID) {
			model.clickSlottedResource({
				cityID: data.cityID,
				resourceValue: data.resourceValue,
			});
		} else {
			model.clickAvailableResource({ resourceValue: data.resourceValue });
		}
	};

	const onDragEnd: DragEndCallback = (_draggable, status) => {
		if (status === DragEndStatus.RejectedByDropzone) {
			model.deselectSelectedResource();
			audioTrigger("dropReject");
		}
	};

	const onDragDrop: DragDropCallbackT<ResourceSlotData, DropzoneData> = (draggable, dropzone) => {
		const resource = draggable.data;
		const cityID = dropzone.data.cityID;
		const targetResourceValue = dropzone.data.resourceValue;

		if (targetResourceValue) {
			if (cityID) {
				// Swapping two resources
				model.clickSlottedResource({
					cityID: cityID,
					resourceValue: targetResourceValue,
				});
			} else {
				model.clickAvailableResource({
					resourceValue: targetResourceValue,
				});
			}
		} else if (cityID) {
			if (resource.cityID === undefined || !ComponentID.isMatch(cityID, resource.cityID)) {
				// Slot in resource
				model.slotSelectedResource(cityID);
			} else {
				// Dragged and released on the same slot dropzone (or any other cases?)
				model.deselectSelectedResource();
			}
		} else {
			// Dragged and released onto the unassigned dropzone
			model.unslotSelectedResource();
		}
	};

	const disableDND = createMemo(() => {
		return !model.isSlottingAvailable;
	});

	const [gamepadTrayItems, setGamepadTrayItems] = createSignal<GamepadTrayItem[]>([]);

	createEffect(
		on(model.focusedSettlementId, (newId, prevId) => {
			if (ComponentID.isMatch(newId ?? null, prevId ?? null)) {
				return;
			}
			debugGamepadLog("Focused Settlement changed:", getCityName(newId), "( was", getCityName(prevId), ")");
			setGamepadTrayItems(model.getGamepadTrayItems());
		}),
	);
	createEffect(
		on(model.selectedSettlementId, (newId, prevId) => {
			if (ComponentID.isMatch(newId ?? null, prevId ?? null)) {
				return;
			}
			debugGamepadLog("Selected Settlement changed:", getCityName(newId), "( was", getCityName(prevId), ")");
			setGamepadTrayItems(model.getGamepadTrayItems());
		}),
	);
	createEffect(
		on(model.focusedResource, (newValue, prevValue) => {
			if (newValue.resourceValue === prevValue?.resourceValue) {
				return;
			}
			debugGamepadLog(
				"Focused Resource changed:",
				getResourceName(newValue),
				"( was",
				getResourceName(prevValue),
				")",
			);
			setGamepadTrayItems(model.getGamepadTrayItems());
		}),
	);
	createEffect(
		on(model.selectedResource, (newValue, prevValue) => {
			if (newValue.resourceValue === prevValue?.resourceValue) {
				return;
			}
			debugGamepadLog(
				"Selected Resource changed:",
				getResourceName(newValue),
				"( was",
				getResourceName(prevValue),
				")",
			);
			setGamepadTrayItems(model.getGamepadTrayItems());
		}),
	);
	createEffect(
		on(model.ghostResourceFocused, (newValue, prevValue) => {
			if (newValue === prevValue) {
				return;
			}
			debugGamepadLog("Ghost Resource changed focus:", newValue);
			setGamepadTrayItems(model.getGamepadTrayItems());
		}),
	);

	const [autoFocusFilters, setAutoFocusFilters] = createSignal(false);
	const [disableFilters, setDisableFilters] = createSignal(true);
	createEffect(() => {
		setDisableFilters(!model.isInSortAndFilterMode());
		setAutoFocusFilters(model.isInSortAndFilterMode());
	});

	return (
		<CommerceScreenBaseTabContent
			description="LOC_COMMERCE_RESOURCE_ALLOCATION_DESCRIPTION"
			headerBar={
				<div class="flex flex-row w-full items-center">
					<div
						class="flex flex-row items-center"
						style={{ width: "28%" }}
					>
						<div class="text-secondary uppercase font-title flex-auto">
							<L10n.Compose text="LOC_COMMERCE_AVAILABLE_RESOURCES_TITLE" />
						</div>
						<div class="flex flex-row">
							<For each={props.unslottedBonuses}>
								{(unslottedBonus) => (
									<div class="ml-2 flex flex-row">
										<div
											class="size-6 mr-1 bg-cover bg-center"
											style={{
												"background-image": unslottedBonus.iconSrc,
											}}
										/>
										{`+${unslottedBonus.bonusAmount}`}
									</div>
								)}
							</For>
						</div>
					</div>
					<div class="text-secondary uppercase font-title ml-5 pointer-events-none">
						<L10n.Compose text="LOC_COMMERCE_SETTLEMENTS_TITLE" />
					</div>
					<HSlot
						name="filter-and-sort"
						class="ml-8 flex flex-row flex-auto items-center justify-end"
					>
						<div class="font-title uppercase text-secondary">
							<L10n.Compose text="LOC_ADVANCED_START_FILTER" />
						</div>
						<AudioContextProvider segment="Filters">
							<Dropdown
								class="ml-2 mr-4 max-w-60 flex-auto pointer-events-auto min-h-14"
								selectedItemTemplate={(item) => (
									<Show
										when={item !== "DEFAULT"}
										fallback={
											<div class="ml-2">
												<L10n.Stylize text="LOC_COMMERCE_RESOURCE_SORT_FILTER_DEFAULT_LABEL" />
											</div>
										}
									>
										<L10n.Stylize text={`LOC_${item}`} />
									</Show>
								)}
								defaultValue={yieldHighlightDropdownItems[0]}
								onItemSelected={(item) => model.setSelectedResourceFilter(item)}
								disableFocus={disableFilters()}
								autoFocus={autoFocusFilters()}
								tabIndex={1}
							>
								<For each={yieldHighlightDropdownItems}>
									{(item) => (
										<DropdownItem value={item}>
											<Show
												when={item !== "DEFAULT"}
												fallback={
													<div class="ml-2">
														<L10n.Stylize text="LOC_COMMERCE_RESOURCE_SORT_FILTER_DEFAULT_LABEL" />
													</div>
												}
											>
												<L10n.Stylize text={`LOC_${item}`} />
											</Show>
										</DropdownItem>
									)}
								</For>
							</Dropdown>
							<div class="font-title uppercase text-secondary">
								<L10n.Compose text="LOC_COMMERCE_SORT_LABEL" />
							</div>
							<Dropdown
								class="ml-2 max-w-60 flex-auto pointer-events-auto min-h-14"
								selectedItemTemplate={([key]) => (
									<div class="ml-2">
										<L10n.Compose text={key} />
									</div>
								)}
								defaultValue={Object.entries(model.resourceSettlementSortItems)[0]}
								onItemSelected={([_, value]) => model.setSelectedSettlementSortType(value)}
								disableFocus={disableFilters()}
								tabIndex={2}
							>
								<For each={Object.entries(model.resourceSettlementSortItems)}>
									{([key, value]) => (
										<DropdownItem value={[key, value]}>
											<L10n.Compose text={key} />
										</DropdownItem>
									)}
								</For>
							</Dropdown>
						</AudioContextProvider>
					</HSlot>
				</div>
			}
		>
			<GamepadTrayItemProvider
				class="flex-auto"
				name="commerce-resource-gamepad-tray-context"
				items={gamepadTrayItems}
			>
				<div class="text-secondary w-full text-center -top-9 left-0">
					<Show when={!model.isSlottingAvailable}>
						<WarningBanner />
					</Show>
				</div>
				<DragAndDrop
					onDragStart={onDragStart}
					onDragEnd={onDragEnd}
					onDragDrop={onDragDrop}
					disabled={disableDND()}
					debugTrace={DEBUG_DRAG_AND_DROP}
				>
					<SpatialSlot
						name="commerce-resources-container"
						class="flex-auto relative"
					>
						<div class="flex flex-row flex-auto relative">
							<AvailableResourcesContainer {...props} />
							<SlottedResourcesContainer {...props} />
						</div>
					</SpatialSlot>
				</DragAndDrop>
			</GamepadTrayItemProvider>
		</CommerceScreenBaseTabContent>
	);
};

export const CommerceResourcesContainer = ComponentRegistry.register({
	name: "CommerceResourcesContainer",
	createInstance: CommerceResourcesContainerComponent,
	styles: [style],
});
//#endregion
